    private readonly ImageDocumentOperations _documents=new();private readonly ImageLayerOperations _layers=new();
    private static Variant Get(Settings d,string key,Variant fallback=default)=>d.TryGetValue(key,out var value)?value:fallback;
    private static TextParagraph Paragraph(TextEdit owner)=>owner.Get("paragraph").As<TextParagraph>();
    private static int ScalarLength(string value){int count=0;foreach(var rune in value.EnumerateRunes())count++;return count;}
    public void ready(TextEdit owner)
    {
        owner.WrapMode=TextEdit.LineWrappingMode.Boundary;owner.CaretBlink=true;foreach(string key in new[]{"font_color","font_selected_color","font_outline_color","caret_color","selection_color"})owner.AddThemeColorOverride(key,Colors.Transparent);foreach(string key in new[]{"normal","focus","read_only"})owner.AddThemeStyleboxOverride(key,new StyleBoxEmpty());owner.ScrollFitContentHeight=true;owner.TextChanged+=()=>{owner.Set("_signature",0L);owner.Set("_blink",0.0);owner.QueueRedraw();};owner.CaretChanged+=()=>{owner.Set("_blink",0.0);owner.QueueRedraw();};sync_layout(owner);
    }
    public void process(TextEdit owner,double delta){owner.Set("_blink",(owner.Get("_blink").AsDouble()+delta)%1);sync_layout(owner);owner.QueueRedraw();}
    public void sync_layout(TextEdit owner)
    {
        var layer=owner.Get("layer").As<Resource>();var canvas=owner.Get("canvas").As<Control>();if(layer==null||canvas==null)return;var world=_documents.world_transform(canvas.Get("document").As<Resource>(),layer);double zoom=canvas.Get("zoom").AsDouble(),detail=Math.Max(1,zoom*Math.Max(world.X.Length(),world.Y.Length()));owner.Set("detail",detail);owner.Position=canvas.Call("origin").AsVector2()+world.Origin*(float)zoom;owner.Rotation=world.Rotation;owner.Scale=world.Scale*(float)(zoom/detail);var properties=layer.Get("properties").AsGodotDictionary();var schema=GD.Load<CSharpScript>("res://scripts/actors/core/ActorTextSettings.cs");var settings=schema.Call("values",Get(properties,"text_settings")).AsGodotDictionary();if(settings.Count==0)settings=properties;owner.Set("settings",settings);var font=schema.Call("font",settings).As<Font>();owner.Set("font",font);int size=Math.Max(1,Mathf.RoundToInt(Get(settings,"font_size",72).AsDouble()*Get(properties,"text_scale",1).AsDouble()*detail));owner.Set("font_size",size);long signature=unchecked((uint)GD.Hash(new GArray{owner.Text,layer.Get("dimensions"),settings,detail,Get(properties,"alignment",0)}));var paragraph=Paragraph(owner);if(signature!=owner.Get("_signature").AsInt64()){owner.Set("_signature",signature);owner.AddThemeFontOverride("font",font);owner.AddThemeFontSizeOverride("font_size",size);paragraph.Clear();paragraph.Width=(float)(layer.Get("dimensions").AsVector2().X*detail);paragraph.Alignment=(HorizontalAlignment)Get(properties,"alignment",0).AsInt32();paragraph.AddString(owner.Text,font,size);}owner.Size=new Vector2((float)(layer.Get("dimensions").AsVector2().X*detail),(float)Math.Max(_layers.content_dimensions(layer).Y*detail,paragraph.GetSize().Y+font.GetHeight(size)));owner.ScrollVertical=0;owner.ScrollHorizontal=0;
    }
    public long absolute(TextEdit owner,int line,int column){long offset=column;for(int index=0;index<line;index++)offset+=ScalarLength(owner.GetLine(index))+1;return offset;}
    public Vector2I line_column(TextEdit owner,long offset){int count=owner.GetLineCount();for(int index=0;index<count;index++){int length=ScalarLength(owner.GetLine(index));if(offset<=length)return new Vector2I((int)offset,index);offset-=length+1;}return new Vector2I(ScalarLength(owner.GetLine(count-1)),count-1);}
    public void place_caret(TextEdit owner,long offset,long selectFrom){var at=line_column(owner,offset);owner.SetCaretLine(at.Y);owner.SetCaretColumn(at.X);if(selectFrom<0)owner.Deselect();else{var start=line_column(owner,Math.Min(offset,selectFrom));var end=line_column(owner,Math.Max(offset,selectFrom));owner.Select(start.Y,start.X,end.Y,end.X);}owner.Set("_blink",0.0);owner.QueueRedraw();}
    public long hit_text(TextEdit owner,Vector2 at)
    {
        var paragraph=Paragraph(owner);float top=0;for(int index=0;index<paragraph.GetLineCount();index++){float height=paragraph.GetLineSize(index).Y;if(at.Y<top+height||index==paragraph.GetLineCount()-1){float remaining=Math.Max(0,paragraph.Width-paragraph.GetLineWidth(index)),x=paragraph.Alignment==HorizontalAlignment.Center?remaining*.5f:paragraph.Alignment==HorizontalAlignment.Right?remaining:0;return TextServerManager.GetPrimaryInterface().ShapedTextHitTestPosition(paragraph.GetLineRid(index),at.X-x);}top+=height;}return 0;
    }
    public void gui_input(TextEdit owner,InputEvent input)
    {
        if(input is InputEventMouseButton button){if(button.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown&&button.Pressed){owner.EmitSignal("navigation_requested",button);owner.AcceptEvent();return;}if(button.ButtonIndex==MouseButton.Left){if(button.Pressed){long offset=hit_text(owner,button.Position),anchor=button.ShiftPressed?absolute(owner,owner.GetCaretLine(),owner.GetCaretColumn()):offset;owner.Set("_drag_anchor",anchor);owner.CallDeferred("_place_caret",offset,button.ShiftPressed?anchor:-1);}else owner.Set("_drag_anchor",-1L);}}else if(input is InputEventMouseMotion motion&&owner.Get("_drag_anchor").AsInt64()>=0&&(motion.ButtonMask&MouseButtonMask.Left)!=0)owner.CallDeferred("_place_caret",hit_text(owner,motion.Position),owner.Get("_drag_anchor"));
    }
    public Rect2 caret_rect_for_line(TextEdit owner,int line,long offset)
    {
        var paragraph=Paragraph(owner);var carets=TextServerManager.GetPrimaryInterface().ShapedTextGetCarets(paragraph.GetLineRid(line),offset);var leading=Get(carets,"leading_rect",Get(carets,"trailing_rect",new Rect2())).AsRect2();double detail=owner.Get("detail").AsDouble(),zoom=owner.Get("canvas").AsGodotObject().Get("zoom").AsDouble();return new Rect2(new Vector2(leading.Position.X,-paragraph.GetLineAscent(line)),new Vector2((float)Math.Max(1,detail/Math.Max(.01,zoom)),paragraph.GetLineSize(line).Y));
    }
    public void draw(TextEdit owner)
    {
        if(owner.Get("layer").AsGodotObject()==null)return;var font=owner.Get("font").As<Font>();if(font==null)return;var server=TextServerManager.GetPrimaryInterface();var paragraph=Paragraph(owner);long caret=absolute(owner,owner.GetCaretLine(),owner.GetCaretColumn());float top=0;double blink=owner.Get("_blink").AsDouble();bool hasSelection=owner.HasSelection();long selectionStart=hasSelection?absolute(owner,owner.GetSelectionFromLine(),owner.GetSelectionFromColumn()):0,selectionEnd=hasSelection?absolute(owner,owner.GetSelectionToLine(),owner.GetSelectionToColumn()):0;for(int index=0;index<paragraph.GetLineCount();index++){float height=paragraph.GetLineSize(index).Y,baseline=top+paragraph.GetLineAscent(index),remaining=Math.Max(0,paragraph.Width-paragraph.GetLineWidth(index)),x=paragraph.Alignment==HorizontalAlignment.Center?remaining*.5f:paragraph.Alignment==HorizontalAlignment.Right?remaining:0;var rid=paragraph.GetLineRid(index);if(hasSelection)foreach(var span in server.ShapedTextGetSelection(rid,selectionStart,selectionEnd))owner.DrawRect(new Rect2(new Vector2(x+span.X,top),new Vector2(span.Y-span.X,height)),new Color(.15f,.55f,.65f,.35f));var range=paragraph.GetLineRange(index);if(owner.HasFocus()&&blink<.55&&caret>=range.X&&(caret<range.Y||index==paragraph.GetLineCount()-1)){var rect=caret_rect_for_line(owner,index,caret);rect.Position+=new Vector2(x,baseline);owner.DrawRect(rect,new Color("9df4dc"));}top+=height;}int size=owner.Get("font_size").AsInt32();if(paragraph.GetLineCount()==0&&owner.HasFocus()&&blink<.55)owner.DrawLine(Vector2.Zero,new Vector2(0,font.GetHeight(size)),new Color("9df4dc"),1);var settings=owner.Get("settings").AsGodotDictionary();float detail=owner.Get("detail").AsSingle();if(Get(settings,"shadow",false).AsBool())paragraph.Draw(owner.GetCanvasItem(),Get(settings,"shadow_offset",new Vector2(2,2)).AsVector2()*detail,Get(settings,"shadow_color",Colors.Black).AsColor());if(Get(settings,"outline_size",0).AsInt32()>0)paragraph.DrawOutline(owner.GetCanvasItem(),Vector2.Zero,Mathf.RoundToInt(settings["outline_size"].AsDouble()*detail),Get(settings,"outline_color",Colors.Black).AsColor());paragraph.Draw(owner.GetCanvasItem(),Vector2.Zero,Get(settings,"color",Colors.White).AsColor());
    }
}
